-- @no-txn
-- Drives its own transactions, so it opts out of the harness's isolating wrapper
-- (and keeps its own DROP-first cleanup).
--
-- An identity column dropped and re-added in a block after a draw: the re-add's
-- backfill numbers the four rows `1`–`4`, and the block's next insert draws `5` from the
-- new cell. The rollback puts the old cell back at `4` (the draw before the drop), so
-- 18.6 answers `5`.
-- @setup
DROP TABLE IF EXISTS rdc_ident;
CREATE TABLE rdc_ident (x INT, id INT GENERATED BY DEFAULT AS IDENTITY);
INSERT INTO rdc_ident (x) VALUES (1), (2), (3);
BEGIN;
INSERT INTO rdc_ident (x) VALUES (4) RETURNING id;
ALTER TABLE rdc_ident DROP COLUMN id;
ALTER TABLE rdc_ident ADD COLUMN id INT GENERATED BY DEFAULT AS IDENTITY;
INSERT INTO rdc_ident (x) VALUES (5) RETURNING id;
INSERT INTO rdc_ident (x) VALUES (6) RETURNING id;
ROLLBACK;
-- @test
INSERT INTO rdc_ident (x) VALUES (7) RETURNING id;
